/**
 * Module 3: Strategy
 *
 * Master asset allocation and core investment principles.
 */

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTrainingStore } from '../../../../stores/trainingStore';
import { createSanitizedMarkup } from '../../../../lib/utils/sanitizeHtml';
import type { ScreenContent, QuizOption } from '../types';

const MODULE_3_SCREENS: ScreenContent[] = [
  {
    id: 'intro',
    type: 'intro',
    title: 'Welcome to Module 3: Strategy',
    subtitle: 'Master Asset Allocation and Core Investment Principles',
  },
  {
    id: 'three-buckets',
    type: 'content',
    title: 'The Three-Bucket Asset Allocation',
    subtitle: 'Security, Growth, and Dream buckets',
  },
  {
    id: 'core-four',
    type: 'content',
    title: 'The Core Four Principles',
    subtitle: "Ray Dalio's All Seasons portfolio",
  },
  {
    id: 'allocation-quiz',
    type: 'quiz',
    title: 'Test Your Allocation Knowledge',
    question: 'What is the primary purpose of the Security bucket?',
    options: [
      { value: 'a', label: 'Maximum growth through aggressive investments', feedback: 'Incorrect. The Growth bucket is for maximum growth.', isCorrect: false },
      { value: 'b', label: 'Preserve capital and provide liquidity', feedback: 'Correct! Security protects your principal.', isCorrect: true },
      { value: 'c', label: 'Fund retirement luxuries and dreams', feedback: 'Incorrect. That is the Dream bucket.', isCorrect: false },
      { value: 'd', label: 'Generate passive income through high-yield', feedback: 'Incorrect. Security prioritizes preservation over yield.', isCorrect: false },
    ],
    correctAnswer: 'b',
  },
  {
    id: 'rebalance-scenario',
    type: 'scenario',
    title: 'Market Shift Decision',
    scenario: 'You started with 60/40 stocks/bonds. After a bull market, stocks are now 75%.',
    question: 'What do you do?',
    options: [
      { value: 'hold', label: 'Do nothing - let winners run', feedback: 'Risky! You are taking more risk than intended.', isCorrect: false },
      { value: 'rebalance', label: 'Sell stocks, buy bonds to restore 60/40', feedback: 'Wise! Rebalancing locks in gains.', isCorrect: true },
      { value: 'double', label: 'Add more to stocks to ride the trend', feedback: 'Dangerous! This increases exposure when expensive.', isCorrect: false },
    ],
    correctAnswer: 'rebalance',
  },
  {
    id: 'reflection',
    type: 'reflection',
    title: 'Personal Strategy Reflection',
    content: 'Reflect on: Which bucket do you prioritize? Do you have a target allocation?',
  },
  {
    id: 'complete',
    type: 'content',
    title: 'Module 3 Complete!',
    subtitle: 'You have mastered asset allocation principles',
  },
];

function getScreenContent(screen: ScreenContent): string {
  const defaults: Record<string, string> = {
    'three-buckets': `<h2>The Three-Bucket System</h2><div class="grid grid-cols-1 md:grid-cols-3 gap-4 my-6"><div class="bg-dark-bg p-4 rounded"><h3 class="text-primary-teal font-bold">Security Bucket</h3><p>Capital preservation, emergency fund</p></div><div class="bg-dark-bg p-4 rounded"><h3 class="text-green-400 font-bold">Growth Bucket</h3><p>Long-term wealth compounding</p></div><div class="bg-dark-bg p-4 rounded"><h3 class="text-yellow-400 font-bold">Dream Bucket</h3><p>Aspirational goals and luxuries</p></div></div>`,
    'core-four': `<h2>The Core Four: All Seasons Portfolio</h2><ul class="list-disc ml-8 space-y-2"><li>30% Stocks - Growth</li><li>40% Long-term Bonds - Prosperity</li><li>15% Intermediate Bonds - Stability</li><li>15% Gold - Inflation protection</li></ul><p class="mt-4 text-primary-teal">Uncorrelated assets perform in any environment.</p>`,
    'complete': `<h2 class="text-green-400">Congratulations!</h2><p>You completed Module 3: Strategy.</p><ul class="list-disc ml-8"><li>Three-Bucket system</li><li>Core Four principles</li><li>Rebalancing strategies</li></ul>`,
  };
  return defaults[screen.id] || screen.content || '';
}

export default function Module3_Strategy() {
  const navigate = useNavigate();
  const { startModule, recordScreenProgress, completeModule } = useTrainingStore();
  const [currentIndex, setCurrentIndex] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState<string | null>(null);
  const [showFeedback, setShowFeedback] = useState(false);
  const currentScreenData = MODULE_3_SCREENS[currentIndex];
  const totalScreens = MODULE_3_SCREENS.length;
  const moduleId = 'module-3-strategy';

  useEffect(() => { startModule(moduleId); }, [moduleId, startModule]);

  const handleAnswerSelect = (answer: string) => { setSelectedAnswer(answer); setShowFeedback(true); };
  
  const handleNext = () => {
    recordScreenProgress(moduleId, currentScreenData.id, totalScreens);
    const nextIndex = currentIndex + 1;
    if (nextIndex < totalScreens) {
      setCurrentIndex(nextIndex);
      setSelectedAnswer(null);
      setShowFeedback(false);
    } else {
      completeModule(moduleId);
      navigate('/training/hub');
    }
  };

  const handleBack = () => {
    currentIndex > 0 ? setCurrentIndex(currentIndex - 1) : navigate('/training/hub');
    setSelectedAnswer(null);
    setShowFeedback(false);
  };

  const progress = ((currentIndex + 1) / totalScreens) * 100;

  return (
    <div className="min-h-screen bg-gradient-to-br from-dark-bg to-dark-surface py-12 px-4">
      <div className="max-w-4xl mx-auto">
        <div className="mb-6">
          <div className="w-full bg-dark-bg rounded-full h-2">
            <div className="bg-primary-teal h-2 rounded-full transition-all" style={{ width: `${progress}%` }} />
          </div>
        </div>
        <div className="bg-dark-surface border border-dark-border rounded-lg p-8">
          {currentScreenData.title && <h1 className="text-3xl font-bold text-white mb-2">{currentScreenData.title}</h1>}
          {currentScreenData.subtitle && <p className="text-xl text-primary-teal mb-6">{currentScreenData.subtitle}</p>}
          {(currentScreenData.type === 'content' || currentScreenData.type === 'intro' || currentScreenData.type === 'reflection') && (
            <div className="text-gray-300 leading-relaxed prose prose-invert max-w-none"
              dangerouslySetInnerHTML={createSanitizedMarkup(getScreenContent(currentScreenData))} />
          )}
          {(currentScreenData.type === 'quiz' || currentScreenData.type === 'scenario') && currentScreenData.options && (
            <div className="mt-8 space-y-3">
              {currentScreenData.options.map((option: QuizOption) => (
                <button key={option.value} onClick={() => handleAnswerSelect(option.value)} disabled={showFeedback}
                  className={`w-full text-left px-6 py-4 rounded-lg border transition-all ${
                    selectedAnswer === option.value
                      ? showFeedback && option.isCorrect ? 'bg-green-400/20 border-green-400'
                        : showFeedback ? 'bg-red-400/20 border-red-400'
                        : 'bg-primary-teal/20 border-primary-teal'
                      : 'bg-dark-bg border-dark-border hover:border-primary-teal'
                  }`}>
                  <span className="text-gray-200 font-semibold">{option.label}</span>
                </button>
              ))}
            </div>
          )}
          {showFeedback && selectedAnswer && currentScreenData.options && (
            <div className={`mt-6 p-4 rounded-lg border ${
              selectedAnswer === currentScreenData.correctAnswer ? 'bg-green-400/10 border-green-400/30' : 'bg-red-400/10 border-red-400/30'
            }`}>
              <p className="text-gray-300">{currentScreenData.options.find((o: QuizOption) => o.value === selectedAnswer)?.feedback || ''}</p>
            </div>
          )}
          {(currentScreenData.type === 'intro' || currentScreenData.type === 'content' || currentScreenData.type === 'quiz' || currentScreenData.type === 'scenario') && (
            <div className="flex justify-between items-center mt-8">
              <button onClick={handleBack} className="px-6 py-3 rounded-lg border border-dark-border text-gray-300 hover:border-gray-500 font-semibold">← Back</button>
              <button onClick={handleNext} disabled={(currentScreenData.type === 'quiz' || currentScreenData.type === 'scenario') && !showFeedback}
                className="px-6 py-3 rounded-lg bg-primary-teal hover:bg-teal-600 text-white font-semibold disabled:bg-gray-700">
                {currentIndex === totalScreens - 1 ? 'Complete' : 'Next'} →
              </button>
            </div>
          )}
          {currentScreenData.type === 'reflection' && (
            <div className="flex justify-between items-center mt-8">
              <button onClick={handleBack} className="px-6 py-3 rounded-lg border border-dark-border text-gray-300 hover:border-gray-500 font-semibold">← Back</button>
              <button onClick={handleNext} className="px-6 py-3 rounded-lg bg-primary-teal hover:bg-teal-600 text-white font-semibold">Continue →</button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
